/**
 * One Door — one-link digital presence cards.
 *
 * A One Door card is a single self-contained page that works as a digital
 * business card, a Linktree-style link hub, a musician EPK, or a one-page
 * presence for a preacher without a website. The maker takes a person's
 * details and renders the finished page; the API route in
 * src/app/api/one-door stores it and (optionally) publishes it to Vercel.
 *
 * This module is pure TypeScript: no I/O, no secrets, no network. It is
 * safe to import from server routes. QR codes are generated by the API
 * route (qrcode package) and passed in as data URLs.
 */

/** Product name — the single source of truth. Change it here and
 *  the card pages, the maker panel, and the site header follow. */
export const PRODUCT_NAME = "One Door";

export type OneDoorLinkKind =
  | "website"
  | "social"
  | "music"
  | "video"
  | "booking"
  | "sermon"
  | "giving"
  | "other";

export type OneDoorTemplate = "business" | "linkhub" | "musician" | "preacher";

export type OneDoorLink = {
  id: string;
  label: string;
  url: string;
  kind: OneDoorLinkKind;
};

export type OneDoorProfile = {
  name: string;
  roles: string[];
  tagline?: string;
  bio?: string;
  /** data:image/jpeg|png|webp;base64,... — never a remote URL, never a secret. */
  photoDataUrl?: string;
  phone?: string;
  email?: string;
  /** Phone and email are published ONLY when the matching flag is true.
      The panel asks before turning either on. */
  showPhone: boolean;
  showEmail: boolean;
  links: OneDoorLink[];
  template: OneDoorTemplate;
};

export type OneDoorCardMeta = {
  id: string;
  slug: string;
  name: string;
  template: OneDoorTemplate;
  createdAt: string;
  updatedAt: string;
  /** Public Vercel URL once published; empty until then. */
  publishedUrl: string;
};

export type OneDoorCardRecord = OneDoorCardMeta & {
  profile: OneDoorProfile;
};

export const ONE_DOOR_LIMITS = {
  nameMax: 80,
  rolesMax: 4,
  roleMax: 40,
  taglineMax: 160,
  bioMax: 280,
  linksMax: 12,
  linkLabelMax: 40,
  phoneMax: 30,
  emailMax: 120,
  photoMaxBytes: 2_000_000,
  requestMaxBytes: 3_500_000,
} as const;

export const ONE_DOOR_LINK_KINDS: OneDoorLinkKind[] = [
  "website",
  "social",
  "music",
  "video",
  "booking",
  "sermon",
  "giving",
  "other",
];

export const ONE_DOOR_TEMPLATES: OneDoorTemplate[] = [
  "business",
  "linkhub",
  "musician",
  "preacher",
];

export const ONE_DOOR_TEMPLATE_META: Record<
  OneDoorTemplate,
  { label: string; blurb: string; linkSectionTitle: string; primaryKinds: OneDoorLinkKind[] }
> = {
  business: {
    label: "Business card",
    blurb: "Photo, name, what you do, and a way to reach you. The classic card.",
    linkSectionTitle: "Find me",
    primaryKinds: ["website", "social", "booking"],
  },
  linkhub: {
    label: "Link hub",
    blurb: "One link that holds all your links. Like Linktree, but yours.",
    linkSectionTitle: "All my links",
    primaryKinds: ["website", "social", "music", "video", "booking", "sermon", "giving"],
  },
  musician: {
    label: "Musician EPK",
    blurb: "Bio, photo, music, video, shows, and booking. An electronic press kit.",
    linkSectionTitle: "Listen & watch",
    primaryKinds: ["music", "video", "booking", "social", "website"],
  },
  preacher: {
    label: "Preacher page",
    blurb: "Who you are, what you preach, where you are preaching, and how to invite you.",
    linkSectionTitle: "Sermons & more",
    primaryKinds: ["sermon", "video", "booking", "giving", "website", "social"],
  },
};

export const ONE_DOOR_KIND_LABELS: Record<OneDoorLinkKind, string> = {
  website: "Website",
  social: "Social",
  music: "Music",
  video: "Video",
  booking: "Booking",
  sermon: "Sermon",
  giving: "Giving",
  other: "Link",
};

/* ------------------------------------------------------------------ */
/* small helpers                                                       */
/* ------------------------------------------------------------------ */

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function escapeAttr(value: string): string {
  return escapeHtml(value);
}

export function slugifyName(name: string): string {
  const slug = name
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  return slug || "card";
}

export function cardSlug(name: string, id: string): string {
  return `${slugifyName(name)}-${id.slice(0, 8)}`;
}

export function initialsFor(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  const first = parts[0]?.[0] || "M";
  const last = parts.length > 1 ? parts[parts.length - 1][0] : "";
  return (first + last).toUpperCase();
}

function isHttpUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
}

function vcardEscape(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
}

/**
 * JSON-encode a value for embedding inside an inline <script> block.
 * JSON.stringify alone does NOT escape <, >, or & — a name containing
 * "</script>" would break out of the script element. Unicode-escaping
 * those three characters keeps the JSON valid and the page safe.
 */
function jsonForScript(value: string): string {
  return JSON.stringify(value).replace(/</g, "\\u003c").replace(/>/g, "\\u003e").replace(/&/g, "\\u0026");
}

/* ------------------------------------------------------------------ */
/* validation                                                          */
/* ------------------------------------------------------------------ */

export type OneDoorValidation =
  | { ok: true; profile: OneDoorProfile }
  | { ok: false; errors: string[] };

export function validateProfile(input: unknown): OneDoorValidation {
  const errors: string[] = [];
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    return { ok: false, errors: ["Card details are missing."] };
  }
  const value = input as Record<string, unknown>;
  const asString = (field: string): string =>
    typeof value[field] === "string" ? (value[field] as string).trim() : "";

  const name = asString("name");
  if (!name) errors.push("A name is required.");
  if (name.length > ONE_DOOR_LIMITS.nameMax) errors.push("Name is too long.");

  const rawRoles = value.roles;
  const roles: string[] = Array.isArray(rawRoles)
    ? rawRoles.filter((r): r is string => typeof r === "string").map(r => r.trim()).filter(Boolean)
    : [];
  if (roles.length < 1) errors.push("Add at least one role (what this person does).");
  if (roles.length > ONE_DOOR_LIMITS.rolesMax) errors.push("Keep it to four roles at most.");
  if (roles.some(r => r.length > ONE_DOOR_LIMITS.roleMax)) errors.push("Each role must be short.");

  const tagline = asString("tagline");
  if (tagline.length > ONE_DOOR_LIMITS.taglineMax) errors.push("Tagline is too long.");
  const bio = asString("bio");
  if (bio.length > ONE_DOOR_LIMITS.bioMax) errors.push("Bio is too long.");

  const template = asString("template") as OneDoorTemplate;
  const safeTemplate: OneDoorTemplate = (ONE_DOOR_TEMPLATES as string[]).includes(template)
    ? template
    : "business";

  const phone = asString("phone");
  const email = asString("email");
  const showPhone = value.showPhone === true;
  const showEmail = value.showEmail === true;
  if (phone.length > ONE_DOOR_LIMITS.phoneMax) errors.push("Phone number is too long.");
  if (phone && !/^[+()\-.\s\d]+$/.test(phone)) errors.push("Phone number looks invalid.");
  if (email.length > ONE_DOOR_LIMITS.emailMax) errors.push("Email address is too long.");
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push("Email address looks invalid.");
  if (showPhone && !phone) errors.push("Turned on showing the phone number, but no phone number was given.");
  if (showEmail && !email) errors.push("Turned on showing the email address, but no email address was given.");

  const rawLinks = value.links;
  const links: OneDoorLink[] = [];
  if (rawLinks !== undefined) {
    if (!Array.isArray(rawLinks)) {
      errors.push("Links must be a list.");
    } else {
      if (rawLinks.length > ONE_DOOR_LIMITS.linksMax) errors.push("Keep it to twelve links at most.");
      rawLinks.forEach((item, index) => {
        if (!item || typeof item !== "object" || Array.isArray(item)) {
          errors.push(`Link ${index + 1} is not valid.`);
          return;
        }
        const link = item as Record<string, unknown>;
        const label = typeof link.label === "string" ? link.label.trim() : "";
        const url = typeof link.url === "string" ? link.url.trim() : "";
        const kind = typeof link.kind === "string" ? link.kind : "other";
        if (!label) errors.push(`Link ${index + 1} needs a label.`);
        if (label.length > ONE_DOOR_LIMITS.linkLabelMax) errors.push(`Link ${index + 1} label is too long.`);
        if (!url || !isHttpUrl(url)) errors.push(`Link ${index + 1} needs a full web address starting with http.`);
        links.push({
          id: typeof link.id === "string" && link.id ? link.id : `link-${index + 1}`,
          label,
          url,
          kind: (ONE_DOOR_LINK_KINDS as string[]).includes(kind) ? (kind as OneDoorLinkKind) : "other",
        });
      });
    }
  }

  let photoDataUrl: string | undefined;
  const rawPhoto = value.photoDataUrl;
  if (typeof rawPhoto === "string" && rawPhoto) {
    const match = /^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+/=]+)$/.exec(rawPhoto.trim());
    if (!match) {
      errors.push("Photo must be a JPEG, PNG, or WebP image.");
    } else {
      const bytes = Math.floor((match[2].length * 3) / 4);
      if (bytes > ONE_DOOR_LIMITS.photoMaxBytes) errors.push("Photo is too large. Keep it under 2 MB.");
      else photoDataUrl = rawPhoto.trim();
    }
  }

  if (errors.length > 0) return { ok: false, errors };
  return {
    ok: true,
    profile: {
      name,
      roles,
      tagline: tagline || undefined,
      bio: bio || undefined,
      photoDataUrl,
      phone: phone || undefined,
      email: email || undefined,
      showPhone,
      showEmail,
      links,
      template: safeTemplate,
    },
  };
}

/* ------------------------------------------------------------------ */
/* vCard                                                               */
/* ------------------------------------------------------------------ */

export function buildVCard(profile: OneDoorProfile): string {
  const lines = ["BEGIN:VCARD", "VERSION:3.0", `FN:${vcardEscape(profile.name)}`];
  if (profile.roles.length > 0) lines.push(`TITLE:${vcardEscape(profile.roles.join(", "))}`);
  if (profile.showPhone && profile.phone) lines.push(`TEL;TYPE=CELL:${vcardEscape(profile.phone)}`);
  if (profile.showEmail && profile.email) lines.push(`EMAIL:${vcardEscape(profile.email)}`);
  const website = profile.links.find(l => l.kind === "website");
  if (website) lines.push(`URL:${vcardEscape(website.url)}`);
  if (profile.tagline) lines.push(`NOTE:${vcardEscape(profile.tagline)}`);
  lines.push("END:VCARD");
  return lines.join("\r\n") + "\r\n";
}

/* ------------------------------------------------------------------ */
/* card page rendering                                                 */
/* ------------------------------------------------------------------ */

export function renderCardHtml(
  profile: OneDoorProfile,
  opts: { pageUrl: string; qrDataUrl: string },
): string {
  const meta = ONE_DOOR_TEMPLATE_META[profile.template];
  const orderedLinks = [...profile.links].sort((a, b) => {
    const ai = meta.primaryKinds.indexOf(a.kind);
    const bi = meta.primaryKinds.indexOf(b.kind);
    return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
  });
  const vcf = buildVCard(profile);
  const fileName = `${slugifyName(profile.name)}.vcf`;

  const photoBlock = profile.photoDataUrl
    ? `<img class="od-photo" src="${escapeAttr(profile.photoDataUrl)}" alt="Photo of ${escapeAttr(profile.name)}">`
    : `<div class="od-monogram" role="img" aria-label="Photo placeholder">${escapeHtml(initialsFor(profile.name))}</div><p class="od-photo-note">Photo placeholder</p>`;

  const contactButtons: string[] = [];
  if (profile.showPhone && profile.phone) {
    contactButtons.push(`<a class="od-btn od-btn-call" href="tel:${escapeAttr(profile.phone.replace(/[\s()\-]/g, ""))}">Call</a>`);
  }
  if (profile.showEmail && profile.email) {
    contactButtons.push(`<a class="od-btn od-btn-email" href="mailto:${escapeAttr(profile.email)}">Email</a>`);
  }
  contactButtons.push(`<button class="od-btn od-btn-save" type="button" data-save-contact>Save to Contacts</button>`);

  const linkButtons = orderedLinks
    .map(
      l =>
        `<a class="od-link" href="${escapeAttr(l.url)}" target="_blank" rel="noopener noreferrer"><span>${escapeHtml(l.label)}</span><small>${escapeHtml(ONE_DOOR_KIND_LABELS[l.kind])}</small></a>`,
    )
    .join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>${escapeHtml(profile.name)} — ${PRODUCT_NAME}</title>
<meta name="description" content="${escapeAttr([profile.name, ...profile.roles].join(" · "))}">
<style>
*{box-sizing:border-box;margin:0}
body{background:#0b0c0f;color:#f1f2f4;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased;padding:28px 16px 48px}
.od-wrap{max-width:430px;margin:0 auto}
.od-card{background:linear-gradient(160deg,#17150f,#0b0c0f 60%);border:1px solid #554722;border-radius:24px;overflow:hidden;box-shadow:0 18px 50px rgba(0,0,0,.5)}
.od-face{padding:30px 24px 26px;text-align:center}
.od-photo{width:132px;height:132px;object-fit:cover;border-radius:50%;border:2px solid #d7b35d;display:block;margin:0 auto 18px}
.od-monogram{width:132px;height:132px;border-radius:50%;border:2px solid #d7b35d;display:grid;place-items:center;margin:0 auto 10px;font-family:Georgia,serif;font-size:46px;color:#d7b35d;background:linear-gradient(145deg,#191711,#0e0f12)}
.od-photo-note{font-size:11px;color:#858b98;margin-bottom:8px}
.od-face h1{font-size:27px;letter-spacing:-.02em;line-height:1.15}
.od-roles{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin:14px 0 6px}
.od-roles span{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#d7b35d;border:1px solid #554722;border-radius:999px;padding:6px 11px}
.od-tagline{font-family:Georgia,serif;font-style:italic;font-size:15px;line-height:1.5;color:#c7cbd3;margin:12px auto 0;max-width:330px}
.od-actions{display:flex;flex-wrap:wrap;gap:9px;justify-content:center;margin-top:22px}
.od-btn{min-height:46px;padding:12px 18px;border-radius:12px;font:inherit;font-size:14px;font-weight:650;cursor:pointer;text-decoration:none;display:inline-block}
.od-btn-call{background:#d7b35d;color:#111;border:1px solid #d7b35d}
.od-btn-email{background:transparent;color:#f1f2f4;border:1px solid #554722}
.od-btn-save{background:transparent;color:#d7b35d;border:1px solid #554722}
.od-btn-flip{background:none;border:0;color:#858b98;font:inherit;font-size:12px;cursor:pointer;margin-top:16px;text-decoration:underline}
.od-back{display:none;padding:30px 24px 26px}
.od-card.flipped .od-face{display:none}
.od-card.flipped .od-back{display:block}
.od-back h2{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#d7b35d;margin-bottom:12px}
.od-bio{font-size:14px;line-height:1.65;color:#c7cbd3;margin-bottom:20px}
.od-links{display:grid;gap:9px}
.od-link{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 15px;border:1px solid #2b2f3a;border-radius:13px;background:#14161c;color:#f1f2f4;text-decoration:none;font-size:15px}
.od-link small{font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#858b98}
.od-qr{margin-top:22px;text-align:center}
.od-qr img{width:150px;height:150px;border-radius:12px;border:1px solid #554722;background:#fff;padding:6px}
.od-qr p{font-size:11px;color:#858b98;margin-top:9px;line-height:1.5}
.od-foot{text-align:center;margin-top:20px;font-size:11px;color:#5f6571;line-height:1.6}
.od-foot a{color:#d7b35d}
</style>
</head>
<body>
<main class="od-wrap">
<article class="od-card" id="moCard">
  <section class="od-face">
    ${photoBlock}
    <h1>${escapeHtml(profile.name)}</h1>
    <div class="od-roles">${profile.roles.map(r => `<span>${escapeHtml(r)}</span>`).join("")}</div>
    ${profile.tagline ? `<p class="od-tagline">&ldquo;${escapeHtml(profile.tagline)}&rdquo;</p>` : ""}
    <div class="od-actions">${contactButtons.join("")}</div>
    <button class="od-btn-flip" type="button" data-flip>See links &amp; QR code &#8594;</button>
  </section>
  <section class="od-back">
    <h2>${escapeHtml(meta.linkSectionTitle)}</h2>
    ${profile.bio ? `<p class="od-bio">${escapeHtml(profile.bio)}</p>` : ""}
    <div class="od-links">${linkButtons || `<p class="od-bio">No links added yet.</p>`}</div>
    <div class="od-qr"><img src="${escapeAttr(opts.qrDataUrl)}" alt="QR code for this page"><p>Scan to open this page.<br>${escapeHtml(opts.pageUrl)}</p></div>
    <div class="od-actions"><button class="od-btn od-btn-save" type="button" data-save-contact>Save to Contacts</button></div>
    <button class="od-btn-flip" type="button" data-flip>&#8592; Back to card</button>
  </section>
</article>
<p class="od-foot">Made with ${PRODUCT_NAME}.<br><a href="${escapeAttr(opts.pageUrl)}">${escapeHtml(opts.pageUrl)}</a></p>
</main>
<script>
(function(){
  var vcf = ${jsonForScript(vcf)};
  var fileName = ${jsonForScript(fileName)};
  function saveContact(){
    var blob = new Blob([vcf], { type: "text/vcard" });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = fileName;
    document.body.appendChild(a); a.click();
    setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 500);
  }
  document.querySelectorAll("[data-save-contact]").forEach(function(b){ b.addEventListener("click", saveContact); });
  document.querySelectorAll("[data-flip]").forEach(function(b){
    b.addEventListener("click", function(){ document.getElementById("moCard").classList.toggle("flipped"); });
  });
})();
</script>
</body>
</html>`;
}

